assert set(p['study']['evidence_refs'])<=set(runtime['context']['allowed_observation_ids'])
assert p['parent_trial'] in runtime['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
ancestor=ast.parse(Path('history_g3_r0053_fixed_bit_negative_bridge.py').read_text())
old_functions={n.name:n for n in ancestor.body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
old_model=next(n for n in ancestor.body if isinstance(n,ast.ClassDef) and n.name=='Model')
old_methods={n.name:n for n in old_model.body if isinstance(n,ast.FunctionDef)}
canonical_ast=[]
for v in p['variants']:
 src=Path(v['file']).read_text()
 compile(src,v['file'],'exec')
 tree=ast.parse(src)
 config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets)))
 assert config==v['config']
 model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 methods={n.name:n for n in model.body if isinstance(n,ast.FunctionDef)}
 defaults={a.arg:ast.literal_eval(d) for a,d in zip(methods['__init__'].args.args[-len(methods['__init__'].args.defaults):],methods['__init__'].args.defaults)}
 for key,value in config.items():
  assert key in defaults,key
  default=defaults[key]
  assert list(default)==value if isinstance(default,tuple) else default==value,(key,default,value)
 for name,node in old_methods.items():
  if name"'!='"'__init__':assert ast.dump(node)==ast.dump(methods[name]),(v['name'],name)
 # Constructor changes only the two defaults and accepted assignment vocabulary.
 old_init=copy.deepcopy(old_methods['__init__']);new_init=copy.deepcopy(methods['__init__'])
 for f in (old_init,new_init):
  for i,a in enumerate(f.args.args[-len(f.args.defaults):]):
   if a.arg in ('orthogonal_assignment','orthogonal_orientation'):f.args.defaults[i]=ast.Constant('normalized')
 # New assignment is the sole constructor-body delta.
 for node in ast.walk(new_init):
  if isinstance(node,ast.Tuple):node.elts=[x for x in node.elts if not (isinstance(x,ast.Constant) and x.value=='click_line_oriented')]
 assert ast.dump(old_init)==ast.dump(new_init),(v['name'],'constructor delta')
 functions={n.name:n for n in tree.body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
 for name,node in old_functions.items():
  if name not in ('Model','_CollectedContextTransfer','_reduce_context_transfer'):
   assert ast.dump(node)==ast.dump(functions[name]),(v['name'],name)
 old_collection=copy.deepcopy(old_functions['_CollectedContextTransfer']);new_collection=copy.deepcopy(functions['_CollectedContextTransfer'])
 for node in ast.walk(new_collection):
  if isinstance(node,ast.Tuple):node.elts=[x for x in node.elts if not (isinstance(x,ast.Constant) and x.value=='click_line_oriented')]
 assert ast.dump(old_collection)==ast.dump(new_collection),'collector only vocabulary'
 for node in ast.walk(tree):
  if isinstance(node,ast.Import):assert all(a.name.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'} for a in node.names)
  if isinstance(node,ast.ImportFrom):assert node.module.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Name):assert node.func.id not in ('open','exec','eval','compile','__import__')
 # All executable AST except literal config and selector defaults must match.
 normalized=copy.deepcopy(tree)
 for node in normalized.body:
  if isinstance(node,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in node.targets):node.value=ast.Dict(keys=[],values=[])
 for node in ast.walk(normalized):
  if isinstance(node,ast.FunctionDef) and node.name=='__init__':
   for i,a in enumerate(node.args.args[-len(node.args.defaults):]):
    if a.arg in ('orthogonal_assignment','orthogonal_orientation'):node.args.defaults[i]=ast.Constant('normalized')
 canonical_ast.append(ast.dump(normalized))
 digest=hashlib.sha256(src.encode()).hexdigest()
 assert digest in v['note']
 print(v['name'],digest,'syntax/config/inherited-source OK')
assert len(set(canonical_ast))==1
print('PASS recursive study schema, protocol/evidence/lineage, four standalone cells, permitted imports, identical forward/loss/helpers/constructor allocation, collector VJP preservation, common executable AST and hashes')
